use verus::prelude::*;

verus! {

    /// Returns true iff there exists an index i such that
    /// 0 <= i < a.len() - 1 and a[i] + 1 == a[i+1].
    pub fn contains_consecutive_numbers(a: &Vec<i32>) -> (result: bool)
        ensures
            // The result is exactly the existence of some adjacent pair
            result == exists |i: nat| i < a.len() - 1 && a[i] + 1 == a[i + 1]
    {
        let n: nat = a.len();
        // If fewer than two elements, no adjacent pair can exist.
        if n < 2 {
            return false;
        }

        // We'll scan from 0 up to n-2, looking for the first place
        // where a[i] + 1 == a[i+1].
        let mut i: nat = 0;
        let mut found: bool = false;

        // Loop until we've either found a consecutive pair, or we've
        // exhausted all valid i (i+1 < n).
        while i + 1 < n && !found
            invariant i <= n
            invariant
                // `found` records exactly whether in the range [0, i)
                // we've already seen a consecutive pair.
                found == exists |j: nat| j < i && a[j] + 1 == a[j + 1]
            decreases n - i
        {
            if a[i] + 1 == a[i + 1] {
                found = true;
            } else {
                i = i + 1;
            }
        }

        // At this point:
        // - if found == true, then indeed there is some j < i with a[j]+1==a[j+1];
        // - otherwise i+1 >= n, so i >= n-1, and thus “exists j<i” ranges over
        //   all 0..n-2, exactly the domain we care about.
        //
        // Hence `found` meets the postcondition.
        found
    }

}